const { withGradleProperties } = require("@expo/config-plugins");

// android/ is generated by `expo prebuild`, so Gradle settings must come from a config plugin.
const RELEASE_GRADLE_PROPERTIES = {
  "android.enableMinifyInReleaseBuilds": "true",
  "android.enableShrinkResourcesInReleaseBuilds": "true",
  // x86/x86_64 are only needed for emulators; override per build with -PreactNativeArchitectures.
  reactNativeArchitectures: "armeabi-v7a,arm64-v8a",
};

function setProperty(properties, key, value) {
  const existing = properties.find(
    item => item.type === "property" && item.key === key,
  );

  if (existing) {
    existing.value = value;
    return;
  }

  properties.push({ type: "property", key, value });
}

function withAndroidReleaseOptimizations(config) {
  return withGradleProperties(config, config => {
    for (const [key, value] of Object.entries(RELEASE_GRADLE_PROPERTIES)) {
      setProperty(config.modResults, key, value);
    }

    return config;
  });
}

module.exports = withAndroidReleaseOptimizations;
